head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getChildrenRowIndexArray]<br/>DrillDown 이 적용되었을때 특정 Row 의 직계 자식 Row 인덱스값을 배열로 반환합니다.",
    "validation" : [
        "inputType='drilldown' 인 Column 이 정의되어야 동작합니다.",
        "rowIndex(필수) 파라미터로 직계 자식 Row 의 인덱스를 조회할 Body Row 의 인덱스를 설정합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다.",
        "파라미터에 해당하는 Row 의 직계 자식 Row 인덱스값을 1차원 배열로 반환합니다.",
        "반환되는 배열은 직계 자식만 순서대로 포함하며 손자 등 그 이하 자손은 포함하지 않습니다.",
        "파라미터에 해당하는 Row 의 인덱스는 포함되지 않으며 자식이 없는 Leaf Row 이면 빈 배열을 반환합니다.",
        "반환되는 Row 의 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - inputType="drilldown" 트리 컬럼 + depth(계층) 데이터로 3단계 DrillDown 그리드 구성
//  - getChildrenRowIndexArray 의 rowIndex 및 반환 인덱스는 모두 "바인딩된 DataList 기준" 이다
//    (엔진 gridViewApiController.getChildrenRowIndexArray → drilldown.getChildrenRowArr(rowIndex).
//     getChildrenRowArr 는 getChildRowArr(rowIndex) 를 getAllChild 없이(false) 호출 → DataList 를
//     rowIndex+1 부터 정방향 스캔하며 depth 가 부모 depth+1 인 Row(=직계 자식) 만 childRowIndexArr 에
//     push, depth 가 부모 이하가 되면 break. → 직계 자식만 DataList 순서대로 담아 1차원 배열로 반환.
//     자기 자신은 미포함, 자식 없으면 [] 반환).
//    → 표시 접힘/펼침과 무관하게 DataList 인덱스로 직접 조회 가능. getRealRowIndex 변환 불필요.
//  - ★ getDescendantRowIndexArray(모든 자손) 와 구별 : 이 메소드는 손자를 제외한 직계 자식만 반환.
//    (getDescendant 는 getChildRowArr(rowIndex, true) 로 손자까지 모든 자손 포함)
//  - 데이터(DataList idx): 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3) > 개발1팀(4), 관리팀(독립)(5)=Leaf
//  - showDepth="1" 로 초기에는 depth1(영업본부/개발본부/관리팀)만 표시되고 자식은 접힘.
//    자식이 화면에 안 보여도 DataList 인덱스로 직계 자식 조회가 동작함을 확인.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] inputType=drilldown 트리 그리드. rowIndex 와 반환 인덱스 모두 바인딩된 DataList 기준(표시 접힘/펼침과 무관). 데이터(DataList idx): 영업본부(0) > [영업1팀(1) > 김영업(2)·이영업(3), 영업2팀(4) > 박영업(5), 영업3팀(6)]. 초기 showDepth=1 로 자식은 접혀 화면에 없지만 DataList 인덱스로 직접 조회 가능.\n[절차] par_rowIndex(DataList 인덱스) 선택 후 getChildrenRowIndexArray 버튼 클릭.\n[확인] 조회 Row 의 직계 자식만 순서대로 1차원 배열로 반환. 영업본부(0) -> [1,4,6] 직계 3개(손자 2·3·5 미포함), 영업1팀(1) -> [2,3] 직계 2개, 영업2팀(4) -> [5] 직계 1개, 김영업(2) -> [] Leaf. 조회 Row 자신은 미포함. (손자까지 모든 자손을 반환하는 getDescendantRowIndexArray 와 구별 : 영업본부(0) 은 getDescendant 면 [1,2,3,4,5,6] 이지만 getChildren 은 [1,4,6])."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (본부=1, 팀=2, 사원=3)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 부모 바로 아래에 그 자식이 위치(엔진 drilldown 은 순서 기반)
    //  - idx0 영업본부(depth1) : 직계 자식 3개 [1,4,6]
    //      > idx1 영업1팀(depth2) : 직계 자식 2개 [2,3] > idx2 김영업(depth3), idx3 이영업(depth3)
    //      > idx4 영업2팀(depth2) : 직계 자식 1개 [5] > idx5 박영업(depth3)
    //      > idx6 영업3팀(depth2) : Leaf []
    let jsonData = [
        { "name": "영업본부", "amount": 100, "depth": 1 },
        { "name": "영업1팀",  "amount": 110, "depth": 2 },
        { "name": "김영업",   "amount": 111, "depth": 3 },
        { "name": "이영업",   "amount": 112, "depth": 3 },
        { "name": "영업2팀",  "amount": 120, "depth": 2 },
        { "name": "박영업",   "amount": 121, "depth": 3 },
        { "name": "영업3팀",  "amount": 130, "depth": 2 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성 (DrillDown 트리 컬럼)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getChildrenRowIndexArray (직계 자식 Row 인덱스 배열) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="360" style="" inputType="text" id="hcol1" value="조직(drilldown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="360" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [getChildrenRowIndexArray] : par_rowIndex(DataList 인덱스)의 직계 자식 Row 인덱스(DataList 기준)를 1차원 배열로 반환
//  - 반환 : 직계 자식만 순서대로 담긴 배열 (손자 등 그 이하 자손 미포함) / 자식 없는 Leaf 는 빈 배열 []
//  - 조회 Row 자신의 인덱스는 배열에 포함되지 않음
scwin.btn_getChildrenRowIndexArray_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    let result = target1.getChildrenRowIndexArray(rowIndex);

    b.setReturnValue("getChildrenRowIndexArray(" + rowIndex + ") 반환 : " + JSON.stringify(result));

    // DataList 기준 직계 자식 매핑 (Leaf 이면 빈 배열)
    let baseName = dlt_bind.getCellData(rowIndex, "name");
    let childText;
    if (!result || result.length === 0) {
        childText = "(직계 자식 없음 - 빈 배열)";
    } else {
        childText = result.map(function (idx) { return "idx" + idx + "(" + dlt_bind.getCellData(idx, "name") + ")"; }).join(", ");
    }
    b.setReturnValue("조회 Row : idx" + rowIndex + "(" + baseName + ") -> 직계 자식 : " + childText);
};
